function LadderStruggleComponent:__init()
    self._ticketsNum = nil       --门票数量
    self._ticketsRecoverTime = nil --距离下一张门票恢复时间

    self.ticketMaxNum = nil     -- 门票最大数量
    self.ticketAddTime = nil    -- 门票多长时间回复一张

    self.refreshBtnTimer = 0    -- 刷新按钮的计时器
    self.enterHomeRefreshChanllengerTimer = 0   -- 进入home页面时刷新挑战者的计时器

    local param21 = CfUtils.GetCfVo(SettingIdParamVo, ParamVo, 21)
    if isNotNull(param21) then
        MaxRank = checkInt(param21.num)
    end
end

function LadderStruggleComponent:__delete()
    self._ticketsNum = nil       --门票数量
    self._ticketsRecoverTime = nil --距离下一张门票恢复时间

    self.ticketMaxNum = nil     -- 门票最大数量
    self.ticketAddTime = nil    -- 门票多长时间回复一张
    
    self.refreshBtnTimer = 0    -- 刷新按钮的计时器
    self.enterHomeRefreshChanllengerTimer = 0   -- 进入home页面时刷新挑战者的计时器
    
    if isNotNull(self.co_refreshBtn) then
        cs_coroutine.stop(self.co_refreshBtn)
        self.co_refreshBtn = nil
    end
    if isNotNull(self.co_enterHomeRefreshBtn) then
        cs_coroutine.stop(self.co_enterHomeRefreshBtn)
        self.co_enterHomeRefreshBtn = nil
    end
end

function LadderStruggleComponent:UpdateTicketData(num, recoverTime)
    self:SetCurTicketCount(num)
    self._ticketsRecoverTime = recoverTime
    self:StartTimeDown()
end

--恢复时间
function LadderStruggleComponent:GetTicketsRecoverTime()
    return self._ticketsRecoverTime
end

--门票数量
function LadderStruggleComponent:GetCurTicketCount()
    return self._ticketsNum
end

function LadderStruggleComponent:SetCurTicketCount(count)
    self._ticketsNum = count
    
    -- 同步更新playComponent里面的门票数量
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo =  playerComponent:GetPlayerDojo()
    playerDojo[TicketName] = self._ticketsNum
end

function LadderStruggleComponent:AddTicketCount(num)
    self:SetCurTicketCount(self._ticketsNum + num)
end

function LadderStruggleComponent:StartTimeDown()
    self:ClearTimeDown()
    local maxNum = self:GetMaxTicketNum()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if self._ticketsNum < maxNum then
            self._ticketsRecoverTime = self._ticketsRecoverTime - 1
            if self._ticketsRecoverTime == 0 then
                self:AddTicketCount(1)
                Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, nil)
            elseif self._ticketsRecoverTime < 0 then
                self._ticketsRecoverTime = self:GetTicketAddTime()
            end
        else
            self._ticketsRecoverTime = 0
        end
    end, CountDownTime, false, true)
end

function LadderStruggleComponent:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function LadderStruggleComponent:GetMaxTicketNum()
    local vo = CfUtils.GetCfVo(SettingIdParamVo, ParamVo, 7)
    if not isNull(vo) then
        self.ticketMaxNum = checkInt(vo.num)
    else
        self.ticketMaxNum = 5
    end

    print("[全局天赋] 3队异步PVP门票上限 加成前 ", self.ticketMaxNum)
    -- 全局天赋加成
    local thisSystemId = Constants.SystemToggleIds.Id2007
    ---@type GlobalTalentMgr
    local instance = GlobalTalentMgr:GetInstance()
    self.ticketMaxNum = instance:CalcNum(self.ticketMaxNum, Constants.GlobalTalentEffectId.Id_11, false, function(info)
        if info == nil then
            return false
        end
        if info.vo == nil then
            return false
        end
        local systemId = checkNumber(info.vo.param1)
        return thisSystemId == systemId
    end)
    print("[全局天赋] 3队异步PVP门票上限 加成后 ", self.ticketMaxNum)

    return self.ticketMaxNum
end

function LadderStruggleComponent:GetTicketAddTime()
    if isNull(self.ticketAddTime) then
        local vo = CfUtils.GetCfVo(SettingIdParamVo, ParamVo, 8)
        if not isNull(vo) then
            self.ticketAddTime = checkInt(vo.num)
        else
            self.ticketAddTime = 7200
        end
    end
    return self.ticketAddTime
end

function LadderStruggleComponent:GetBtnRefreshTime()
    return self.refreshBtnTimer
end

function LadderStruggleComponent:StartRefreshBtnCoolDown()
    if RefreshBtnTime == -1 then
        local param4 = CfUtils.GetCfVo(SettingIdParamVo, ParamVo, 4)
        RefreshBtnTime = checkInt(param4.num)
    end
    if isNotNull(self.co_refreshBtn) then
        return
    end
    -- 开始计时
    self.co_refreshBtn = cs_coroutine.start(function()
        self.refreshBtnTimer = RefreshBtnTime
        while self.refreshBtnTimer > 0 do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            self.refreshBtnTimer = self.refreshBtnTimer - 1
            -- print("[大乱斗] 组件 刷新计时", self.refreshBtnTimer)
        end
        self.co_refreshBtn = nil
    end)
end

function LadderStruggleComponent:EnterHomeNeedRefresh()
    return self:GetEnterHomeRefreshChallengerTimer() <= 0
end

function LadderStruggleComponent:GetEnterHomeRefreshChallengerTimer()
    return self.enterHomeRefreshChanllengerTimer
end

function LadderStruggleComponent:StartEnterHomeRefreshCoolDown()
    if RefreshBtnTime == -1 then
        local param4 = CfUtils.GetCfVo(SettingIdParamVo, ParamVo, 4)
        RefreshBtnTime = checkInt(param4.num)
    end
    if isNotNull(self.co_enterHomeRefreshBtn) then
        return
    end
    -- 开始计时
    self.co_enterHomeRefreshBtn = cs_coroutine.start(function()
        self.enterHomeRefreshChanllengerTimer = RefreshBtnTime
        while self.enterHomeRefreshChanllengerTimer > 0 do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            self.enterHomeRefreshChanllengerTimer = self.enterHomeRefreshChanllengerTimer - 1
            -- print("[大乱斗] 组件 home刷新计时", self.enterHomeRefreshChanllengerTimer)
        end
        self.co_enterHomeRefreshBtn = nil
    end)
end

--- 刷新我的排名
---@param newRank any
function LadderStruggleComponent:OnMyRankRefresh(newRank)
    local newRank = checkInt(newRank)

    local isNewSeason = newRank == 0
    newRank = isNewSeason and MaxRank or newRank    -- 新赛季一开始下发的rank为0

    local historyRank = PlayerPrefsUtility.GetEncryptedInt(self.PlayerRankId, MaxRank)
    local isNew = newRank ~= historyRank
    if isNew then
        PlayerPrefsUtility.SetEncryptedInt(self.PlayerRankId, newRank)
        self:SetNewRankState(1)
    end

    local isDown = newRank > historyRank
    if isNewSeason then
        -- 新赛季会清除所有的战斗记录
        self:SetNewRecordState(0)
    else
        if isDown then
            self:SetNewRecordState(1)
        end
    end
    
    return isNew, isDown
end

function LadderStruggleComponent:GetMyRank()
    return PlayerPrefsUtility.GetEncryptedInt(self.PlayerRankId, MaxRank)
end

function LadderStruggleComponent:SetNewRankState(state)
    PlayerPrefsUtility.SetEncryptedInt(self.NewRankId, state)
end

function LadderStruggleComponent:HasNewRank()
    return PlayerPrefsUtility.GetEncryptedInt(self.NewRankId, 0) == 1
end

function LadderStruggleComponent:SetNewRecordState(state)
    PlayerPrefsUtility.SetEncryptedInt(self.NewRecordId, state)
end

function LadderStruggleComponent:HasNewRecord()
    return PlayerPrefsUtility.GetEncryptedInt(self.NewRecordId, 0) == 1
end

return LadderStruggleComponent